package com.garagedesk.service; import com.garagedesk.entity.ServiceBay; import com.garagedesk.exception.ResourceNotFoundException; import com.garagedesk.repo.ServiceBayRepository; import org.springframework.stereotype.Service; import java.util.*; @Service public class BayService{final ServiceBayRepository r;public BayService(ServiceBayRepository r){this.r=r;}public List<ServiceBay> all(){return r.findAll();}public ServiceBay get(Long id){return r.findById(id).orElseThrow(()->new ResourceNotFoundException("Bay not found: "+id));}public ServiceBay save(ServiceBay x){return r.save(x);}public ServiceBay update(Long id,ServiceBay x){ServiceBay b=get(id);b.setBayNumber(x.getBayNumber());b.setBayType(x.getBayType());b.setActive(x.isActive());return r.save(b);}public void delete(Long id){r.delete(get(id));}}
